<template>
<section class="container py-4 management-page integration-settings">
 <header class="management-heading"><div><p class="management-eyebrow">Superadmin</p><h1>{{ tr('Configuración','Settings') }}</h1><p>{{ tr('Controla WhatsApp, inteligencia artificial y límites por iglesia.','Control WhatsApp, AI and limits per church.') }}</p></div></header>
 <router-link to="/superadmin/whatsapp-tools" class="btn btn-outline-secondary mb-3">{{ tr('Ver acciones del asistente WhatsApp','View WhatsApp assistant actions') }}</router-link>
 <label>{{ tr('Iglesia','Church') }}<select v-model="church" class="form-select" :disabled="saving"><option value="">{{ tr('Seleccionar iglesia','Select church') }}</option><option v-for="item in churches" :value="String(item.id)" :key="item.id">{{ item.name }}</option></select></label>
 <p v-if="error" class="alert alert-danger mt-3" role="alert">{{ error }}</p><p v-if="notice" class="alert alert-success mt-3" role="status">{{ notice }}</p><p v-if="loading" role="status">{{ tr('Cargando…','Loading…') }}</p>
 <form v-if="settings && !loading" class="management-surface integration-form" @submit.prevent="save">
 <p class="integration-info">{{ tr('Credenciales compartidas del servidor. No se almacenan claves por iglesia todavía. Los límites son de solicitudes, no de dólares.','Shared server credentials. Per-church keys are not stored yet. Limits count requests, not dollars.') }}</p>
 <fieldset :disabled="saving">
 <section class="integration-section"><h2>WhatsApp</h2><label class="integration-check"><input type="checkbox" v-model="draft.whatsapp_enabled" />{{ tr('Habilitar WhatsApp para esta iglesia','Enable WhatsApp for this church') }}</label><p>{{ tr('Control general para todos sus usuarios. Cada usuario también necesita tener el asistente habilitado.','Master control for all church users. Each user must also have the assistant enabled.') }}</p><p v-if="!settings.pilot" class="alert alert-info">{{ tr('Esta iglesia no es la iglesia piloto configurada. Activar esta opción no cambia el número ni habilita otra iglesia en el piloto actual.','This is not the configured pilot church. This switch does not change the number or enable another church in the current pilot.') }}</p><p v-if="!settings.global_enabled" class="alert alert-warning">{{ tr('El interruptor global del servidor está apagado.','The server-wide switch is off.') }}</p></section>
 <section class="integration-section"><h2>OpenAI</h2><label class="integration-check"><input type="checkbox" v-model="draft.ai_enabled" />{{ tr('Permitir funciones de inteligencia artificial','Allow AI features') }}</label><p>{{ tr('Incluye el asistente WhatsApp y los mensajes de cumpleaños con IA. Los comandos sin IA siguen disponibles si WhatsApp está activo.','Includes WhatsApp AI and AI birthday messages. Non-AI commands remain available when WhatsApp is enabled.') }}</p><p>{{ settings.openai_configured ? `${tr('Modelo compartido','Shared model')}: ${settings.model}` : tr('OpenAI no está configurado en el servidor.','OpenAI is not configured on the server.') }}</p></section>
 <section class="integration-section"><h2>{{ tr('Límites de uso','Usage limits') }}</h2><p>{{ tr('Períodos UTC. Cero bloquea nuevas solicitudes. No pueden superar los límites del servidor; los intentos fallidos también consumen cupo.','UTC periods. Zero blocks new requests. Limits cannot exceed server caps; failed attempts also count.') }}</p><div class="integration-grid"><label v-for="(label,key) in labels" :key="key">{{ label }}<input type="number" min="0" step="1" required class="form-control" v-model.number="draft[key]" /></label></div></section>
 <div class="integration-actions"><button class="btn btn-primary" :disabled="saving">{{ saving?tr('Guardando…','Saving…'):tr('Guardar configuración','Save settings') }}</button><button class="btn btn-outline-secondary" type="button" @click="openUsage">{{ tr('Ver uso y límites','View usage and limits') }}</button></div>
 </fieldset></form>
 <dialog ref="usageDialog" aria-labelledby="integration-usage-title" class="integration-dialog" @click="closeBackdrop" @close="usageOpen=false"><header><h2 id="integration-usage-title">{{ tr('Uso de integraciones','Integration usage') }}</h2><button type="button" class="btn btn-outline-secondary" @click="usageDialog.close()">{{ tr('Cerrar','Close') }}</button></header><p>{{ churches.find(c=>String(c.id)===church)?.name }} · UTC</p><label>{{ tr('Mes','Month') }}<input type="month" v-model="month" class="form-control" @change="loadUsage" /></label><p v-if="usageLoading" role="status">{{ tr('Cargando…','Loading…') }}</p><p v-if="usageError" class="alert alert-danger" role="alert">{{ usageError }}</p><template v-if="usage && !usageLoading"><div class="usage-rows"><article v-for="kind in ['ai','replies','inbox']" :key="kind"><span>{{ labels[`whatsapp_${kind}_limit`] }}</span><strong>{{ usage.usage[kind].used }} / {{ usage.limits[`whatsapp_${kind}_limit`] }}</strong><small>{{ tr('Compartido global','Shared global') }}: {{ usage.usage[kind].global_used }} / {{ usage.usage[kind].global_limit }}</small></article><article><span>{{ labels.birthday_ai_limit }}</span><strong>{{ usage.usage.birthdays.used }} / {{ usage.limits.birthday_ai_limit }}</strong></article></div><p>{{ tr('Vinculados','Linked') }}: {{ usage.linked }} · {{ tr('Esperando primer mensaje','Awaiting first message') }}: {{ usage.pending }}</p><ProviderUsage v-if="usageOpen" :church="church" :month="month" /><h3>{{ tr('Tokens registrados por esta iglesia','Tokens recorded for this church') }}</h3><div v-for="row in usage.tokens" :key="row.feature" class="usage-token"><strong>{{ row.feature === 'birthdays' ? tr('Cumpleaños','Birthdays') : 'WhatsApp' }}</strong><span>{{ tr('Entrada','Input') }}: {{ row.input_tokens }} · {{ tr('Salida','Output') }}: {{ row.output_tokens }}</span></div><p v-if="!usage.tokens.length">{{ tr('Sin tokens registrados en este mes.','No tokens recorded this month.') }}</p><p class="integration-info">{{ tr('Los tokens se registran desde esta actualización, solo cuando OpenAI devuelve datos de uso. No incluye consumos externos ni reconstruye tokens anteriores. Los límites mostrados son los actuales; consulta las facturas de Meta y OpenAI para el costo real.','Tokens are recorded from this update, only when OpenAI returns usage. External usage and historical tokens are not included. Shown limits are current; consult Meta and OpenAI invoices for actual costs.') }}</p></template></dialog>
</section>
</template>
<script setup>
import ProviderUsage from '../ProviderUsage.vue'
import {ref,reactive,computed,onMounted,watch,onUnmounted} from 'vue'
import {apiClient} from '../../services/authApi'
import {useUiStore} from '../../stores/uiStore'
import '../../styles/clerk-management.css'
const ui=useUiStore(),tr=(es,en)=>ui.locale==='es'?es:en
const churches=ref([]),church=ref(''),settings=ref(null),draft=reactive({}),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),usageDialog=ref(null),usageOpen=ref(false),usage=ref(null),usageLoading=ref(false),usageError=ref(''),month=ref(new Date().toISOString().slice(0,7))
let version=0,usageVersion=0
const labels=computed(()=>({whatsapp_ai_limit:tr('IA WhatsApp / mes','WhatsApp AI / month'),whatsapp_replies_limit:tr('Respuestas WhatsApp / mes','WhatsApp replies / month'),whatsapp_inbox_limit:tr('Mensajes recibidos / mes','Incoming messages / month'),whatsapp_daily_limit:tr('Por usuario / día / tipo de operación','Per user / day / operation type'),birthday_ai_limit:tr('IA cumpleaños / mes','Birthday AI / month')}))
const message=e=>Object.values(e.response?.data?.errors||{}).flat().join(' ')||tr('No se pudo completar la operación.','Unable to complete the operation.')
onMounted(async()=>{try{let page=1,last=1;const all=[];do{const {data}=await apiClient.get('/superadmin/churches',{params:{page}});all.push(...data.data);last=data.last_page;page++}while(page<=last);churches.value=all}catch(e){error.value=message(e)}})
watch(church,async()=>{const current=++version;settings.value=null;error.value='';notice.value='';if(!church.value)return;loading.value=true;try{const {data}=await apiClient.get(`/superadmin/churches/${church.value}/integrations`);if(current!==version)return;settings.value=data;Object.assign(draft,data.limits,{whatsapp_enabled:data.whatsapp_enabled,ai_enabled:data.ai_enabled})}catch(e){if(current===version)error.value=message(e)}finally{if(current===version)loading.value=false}})
async function save(){saving.value=true;error.value='';notice.value='';try{settings.value=(await apiClient.put(`/superadmin/churches/${church.value}/integrations`,draft)).data;notice.value=tr('Configuración guardada.','Settings saved.')}catch(e){error.value=message(e)}finally{saving.value=false}}
async function loadUsage(){const current=++usageVersion;usage.value=null;usageError.value='';usageLoading.value=true;try{const {data}=await apiClient.get(`/superadmin/churches/${church.value}/integrations`,{params:{month:month.value}});if(current===usageVersion)usage.value=data}catch(e){if(current===usageVersion)usageError.value=message(e)}finally{if(current===usageVersion)usageLoading.value=false}}
function openUsage(){usageOpen.value=true;usageDialog.value.showModal();loadUsage()}
function closeBackdrop(event){if(event.target===usageDialog.value){const r=usageDialog.value.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)usageDialog.value.close()}}
onUnmounted(()=>{version++;usageVersion++})
</script>
<style scoped>
.integration-settings{min-width:0}.integration-settings>label{display:block;max-width:520px}.integration-form{padding:22px;margin-top:20px}.integration-info{padding:12px;background:#edf4ef;color:#3e5e4b;border-radius:8px;font-size:12px}.integration-section{padding:16px 0;border-bottom:1px solid #dde7df}.integration-section h2,.integration-dialog h2{font-size:18px}.integration-section p,.integration-dialog p{font-size:12px;color:#53675b}.integration-check{display:flex;gap:10px;align-items:center}.integration-check input{width:18px;height:18px;flex:none}.integration-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.integration-grid label{font-size:12px}.integration-grid input{margin-top:6px}.integration-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.integration-settings .btn{width:auto}.integration-settings .btn-primary{color:white;background:#1f6f5c;border-color:#1f6f5c}.integration-settings .btn-outline-secondary{color:#31533f;background:white;border-color:#a1b8a9}.integration-dialog{border:1px solid #cbdcd0;border-radius:14px;padding:24px;width:min(680px,94vw);max-height:88dvh;overflow:auto;color:#284536}.integration-dialog::backdrop{background:#10251b88}.integration-dialog header{display:flex;justify-content:space-between;gap:12px}.integration-dialog h3{font-size:15px}.usage-rows{display:grid;gap:10px;margin:18px 0}.usage-rows article{border:1px solid #dce6df;border-radius:8px;padding:12px;display:grid;grid-template-columns:1fr auto;gap:6px}.usage-rows small{grid-column:1/-1;color:#64766a}.usage-token{display:grid;gap:4px;padding:12px 0;font-size:13px}@media(max-width:600px){.integration-grid{grid-template-columns:1fr}.integration-form,.integration-dialog{padding:16px}}
</style>
